import com.nicolenkoe.hub.AppBuilds;import org.json.*;import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.*;import java.util.concurrent.atomic.*;
public class FreshBuildsTest{public static void main(String[]args)throws Exception{
 JSONObject old=new JSONObject("{\"version\":\"0.64\",\"code\":64}"),newer=new JSONObject("{\"version\":\"0.67\",\"code\":67}"),oldSource=new JSONObject("{\"version\":\"0.64\",\"versionCode\":64,\"downloadUrl\":\"https://nicolenkoe.github.io/hvost-pod-kontrolem-downloads/HvostPodKontrolem-0.64.apk\"}"),freshSource=new JSONObject(oldSource.toString());freshSource.put("version","0.67");freshSource.put("versionCode",67);freshSource.put("downloadUrl","https://nicolenkoe.github.io/hvost-pod-kontrolem-downloads/HvostPodKontrolem-0.67.apk");AtomicInteger mode=new AtomicInteger(),hits=new AtomicInteger();java.util.Set<String> queries=new java.util.HashSet<>();
 HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/release.json",ex->{hits.incrementAndGet();String query=ex.getRequestURI().getRawQuery();if(query!=null)queries.add(query);boolean bypass=query!=null&&query.contains("_hub_check=")&&ex.getRequestHeaders().getFirst("Cache-Control").contains("no-cache");byte[] body=(mode.get()==1?oldSource:bypass?freshSource:oldSource).toString().getBytes(StandardCharsets.UTF_8);if(mode.get()==2){ex.sendResponseHeaders(503,-1);ex.close();return;}ex.sendResponseHeaders(200,body.length);ex.getResponseBody().write(body);ex.close();});server.start();try{String url="http://127.0.0.1:"+server.getAddress().getPort()+"/release.json";JSONObject got=AppBuilds.fetchLatest("hvost-pod-kontrolem",url,old);if(!got.getString("version").equals("0.67")||!got.getString("apk").endsWith("0.67.apk"))throw new AssertionError("Downloaded stale cached 0.64");got=AppBuilds.fetchLatest("hvost-pod-kontrolem",url,old);if(queries.size()!=2)throw new AssertionError("Nonce reused");mode.set(1);try{AppBuilds.fetchLatest("hvost-pod-kontrolem",url,newer);throw new AssertionError("Downgrade accepted");}catch(java.io.IOException expected){}mode.set(2);try{AppBuilds.fetchLatest("hvost-pod-kontrolem",url,old);throw new AssertionError("Offline fell back to saved APK");}catch(java.io.IOException expected){}JSONObject a=new JSONObject("{\"version\":\"0.10\"}"),b=new JSONObject("{\"version\":\"0.9\"}");if(AppBuilds.compare(a,b)<=0)throw new AssertionError("Version ordering");System.out.println("PASS: cached 0.64 -> fresh 0.67 URL, unique cache-busting every click, no downgrade, no silent offline fallback, numeric ordering");}finally{server.stop(0);}
}}
